"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(worked: List[Span], hours: Span) -> None:
    for span in worked:
        outside = span.start < hours.start
        if outside or span.end > hours.end:
            raise ValueError(
                f"{format_span(span)} is outside hours"
            )


def _gap_spans(worked: List[Span], hours: Span):
    cursor = hours.start
    for span in merge_spans(worked):
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < hours.end:
        yield Span(cursor, hours.end)


# ---
def gap_labels(worked: Iterable[Span], hours: Span):
    """A label like 'gap 12:00-13:00 (60 min)' per gap."""
    worked = list(worked)
    _check_inside(worked, hours)
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in _gap_spans(worked, hours)
    ]

