# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import gap_labels


def labels(worked, hours="08:00-18:00"):
    spans = [parse_span(text) for text in worked]
    return gap_labels(spans, parse_span(hours))


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            labels(["08:00-12:00", "13:00-18:00"]),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            labels(["09:00-17:00"]),
            ["gap 08:00-09:00 (60 min)",
             "gap 17:00-18:00 (60 min)"]
        )

    def test_overlaps_leave_no_gap(self):
        worked = ["08:00-13:00", "12:00-18:00"]
        self.assertEqual(labels(worked), [])

    def test_touching_spans_leave_no_gap(self):
        worked = ["08:00-13:00", "13:00-18:00"]
        self.assertEqual(labels(worked), [])

    def test_nobody_working(self):
        self.assertEqual(
            labels([]), ["gap 08:00-18:00 (600 min)"]
        )

    def test_unordered_input(self):
        worked = ["14:00-18:00", "08:00-10:00"]
        self.assertEqual(
            labels(worked), ["gap 10:00-14:00 (240 min)"]
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            labels(["07:00-12:00"])

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            labels(["12:00-18:30"])
